package com.leetcode.backend.dto; import com.leetcode.backend.model.*; public record ContestProblemResponse(Long id,Long problemId,String title,String difficulty,int displayOrder,int points){public static ContestProblemResponse from(ContestProblem p){return new ContestProblemResponse(p.getId(),p.getProblem().getId(),p.getProblem().getTitle(),p.getProblem().getDifficulty(),p.getDisplayOrder(),p.getPoints());}}
